"""Vetted safety cards: first aid and disaster response answered from a fixed, sourced text, never generated by the LLM.

A small model hallucinates (12 to 52 % of answers in our evaluation), which is acceptable for trivia but not for "a snake bit
my son". Questions about an emergency are therefore matched against data/an_toan/the_an_toan.json: a hit speaks the card's
pre-written answer; an emergency question with no matching card gets a fixed "no vetted guidance, call 115 / 112" reply.
Everything else falls through to the normal fast path / RAG / LLM.

Matching works on whole words with Vietnamese diacritics kept: without them "bất tỉnh" equals "bật tính" and "đuối nước"
equals "dưới nước". A card matches by one of its key phrases (a key of 3+ syllables may also match without diacritics) or
by a word combination ("rắn" + "cắn" anywhere in the sentence). The highest priority wins, then the longest match. A card
with context words also needs one of them; a card's block words disable it. A knowledge question ("lũ quét hình thành như
thế nào") is left to the LLM unless it explicitly asks what to do. The word lists live in the card file ("quy_tac") so the
Android port (android/.../SafetyCards.kt) reads exactly the same rules; tests/test_safety.py and bench/eval_safety.py cover them.
"""
from __future__ import annotations

import json
import re
import unicodedata
from dataclasses import dataclass, field
from pathlib import Path


def norm_vi(s: str) -> str:
    """Lower case, NFC, punctuation removed, diacritics kept."""
    s = unicodedata.normalize("NFC", s.lower())
    return re.sub(r"\s+", " ", re.sub(r"[^\w\s]", " ", s)).strip()


def strip_accents(s: str) -> str:
    s = s.replace("đ", "d")
    return unicodedata.normalize("NFC", "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn"))


def _has(t: str, phrase: str) -> bool:
    return f" {phrase} " in f" {t} "


@dataclass
class Card:
    id: str
    title: str
    say: str
    call: str
    priority: int
    keys: list
    keys_ascii: list  # keys of 3+ syllables, without diacritics
    context: list = field(default_factory=list)
    combos: list = field(default_factory=list)  # groups of words; a combo matches when every group has one of its words
    block: list = field(default_factory=list)   # words that disable this card ("nôn ra máu" is not a bleeding wound)
    factual: bool = False  # the card answers a fact ("số cứu hỏa là bao nhiêu"): the knowledge-question gate does not apply


@dataclass
class Match:
    card: Card | None  # None = emergency question without a vetted card (fallback answer)
    say: str
    key: str
    via: str = "luat"  # "luat" = keyword rules, "phan_loai" = the trained classifier (second stage)


def clf_features(text: str) -> list[str]:
    """Word unigrams/bigrams with and without diacritics; identical in SafetyCards.kt."""
    w = norm_vi(text).split()
    a = [strip_accents(x) for x in w]
    f = [f"w:{x}" for x in w] + [f"a:{x}" for x in a]
    f += [f"b:{x}_{y}" for x, y in zip(w, w[1:])] + [f"c:{x}_{y}" for x, y in zip(a, a[1:])]
    return sorted(set(f))


class Classifier:
    """Linear classifier from data/an_toan/phan_loai.json (bench/train_safety_clf.py): card id or "khong"."""

    def __init__(self, path: str | Path):
        d = json.loads(Path(path).read_text(encoding="utf-8"))
        self.classes = d["lop"]
        self.bias = d["lech"]
        self.tau = float(d["nguong"])
        self.margin = float(d["cach_biet"])
        self.w = d["dac_trung"]

    def predict(self, text: str) -> tuple[str, float, float]:
        import math
        z = list(self.bias)
        for f in clf_features(text):
            for c, v in self.w.get(f, ()):
                z[c] += v
        mx = max(z)
        e = [math.exp(x - mx) for x in z]
        s = sum(e)
        p = sorted(((x / s, i) for i, x in enumerate(e)), reverse=True)
        return self.classes[p[0][1]], p[0][0], p[0][0] - p[1][0]


class SafetyCards:
    def __init__(self, path: str | Path, classifier: str | Path | None = None):
        d = json.loads(Path(path).read_text(encoding="utf-8"))
        self.clf = Classifier(classifier) if classifier and Path(classifier).exists() else None
        self.version = d.get("phien_ban", "")
        self.fallback = d["du_phong"]["noi"]
        r = d["quy_tac"]
        self.ask = [norm_vi(x) for x in r["hoi_cach_lam"]]
        self.knowledge = [norm_vi(x) for x in r["kien_thuc"]]
        self.emergency = [norm_vi(x) for x in r["khan_cap"]]
        self.not_emergency = [norm_vi(x) for x in r["khong_khan_cap"]]
        self.year = re.compile(r"(^| )" + r["nam_kien_thuc"] + r"( |$)")
        self.infant = [norm_vi(x) for x in r["tre_nho"]]
        self.infant_month = re.compile(r"(^| )([0-9]+|" + "|".join(r["tre_nho_thang"]) + r") tháng( |$)")
        self.cards = []
        for c in d["the"]:
            keys = sorted({norm_vi(k) for k in c["khoa"]}, key=len, reverse=True)
            self.cards.append(Card(c["id"], c["ten"], c["noi"], c.get("goi", ""), int(c.get("uu_tien", 1)), keys,
                                   [strip_accents(k) for k in keys if len(k.split()) >= 3],
                                   [norm_vi(x) for x in c.get("can_ngu_canh", [])],
                                   [[[norm_vi(w) for w in g] for g in combo] for combo in c.get("to_hop", [])],
                                   [norm_vi(x) for x in c.get("tru", [])], bool(c.get("bo_qua_kien_thuc", False))))
        self.by_id = {c.id: c for c in self.cards}
        self.child = [norm_vi(x) for x in r.get("tre_em", [])]
        # redirects: an adult card -> the infant / child version when the question names a baby or a child, in file order
        self.redirects = [(x["tu_the"], x["sang"], x["khi"]) for x in d.get("chuyen_the", [])]
        if not self.redirects and d.get("tre_so_sinh"):
            self.redirects = [(d["tre_so_sinh"]["tu_the"], d["tre_so_sinh"]["sang"], "so_sinh")]

    def phrases(self) -> list[str]:
        return [c.say for c in self.cards] + [self.fallback]

    def _infant_words(self, t: str) -> bool:
        return any(_has(t, x) for x in self.infant) or bool(self.infant_month.search(t))

    def redirect(self, card: Card, t: str) -> Card:
        """Adult card -> infant / child version when the (normalised) question names a baby or a child."""
        for src, dst, when in self.redirects:
            if card.id == src and dst in self.by_id and (self._infant_words(t) if when == "so_sinh" else any(_has(t, x) for x in self.child)):
                card = self.by_id[dst]
        return card

    def match(self, text: str) -> Match | None:
        t = norm_vi(text)
        if not t:
            return None
        ta = strip_accents(t)
        best, best_rank, best_key = None, (-1, -1), ""
        for c in self.cards:
            if c.context and not any(_has(t, x) for x in c.context):
                continue
            if any(_has(t, x) for x in c.block):
                continue
            key = next((k for k in c.keys if _has(t, k)), None)
            if key is None:
                key = next((k for k in c.keys_ascii if _has(ta, k)), None)
            if key is None:
                for combo in c.combos:
                    words = [next((w for w in g if _has(t, w)), None) for g in combo]
                    if all(words):
                        key = "+".join(words)
                        break
            if key is not None and (c.priority, len(key)) > best_rank:
                best, best_rank, best_key = c, (c.priority, len(key)), key
        ask = any(_has(t, a) for a in self.ask)
        knowledge = any(_has(t, k) for k in self.knowledge) or bool(self.year.search(t))
        if best is not None:
            if knowledge and not ask and not best.factual:
                return None  # an explanation, not a rescue
            best = self.redirect(best, t)
            return Match(best, best.say, best_key)
        if self.clf is not None and (ask or not knowledge):
            c, p, gap = self.clf.predict(text)
            if c != "khong" and c in self.by_id and p >= self.clf.tau and gap >= self.clf.margin:
                card = self.redirect(self.by_id[c], t)
                return Match(card, card.say, f"~{c}:{p:.2f}", "phan_loai")
        te = t
        for x in self.not_emergency:
            te = te.replace(x, " ")
        if (ask or not knowledge) and any(_has(te, e) for e in self.emergency):
            return Match(None, self.fallback, "")
        return None
